from snapshots import delta
def aggregate(attempts):
    totals = {'inputTokens': 0, 'outputTokens': 0, 'cachedInputTokens': 0}
    for attempt in attempts:
        if attempt['status'] != 'completed':
            continue
        change = delta(attempt['before'], attempt['after'])
        for key in totals:
            totals[key] += change[key]
    return {'attempts': len(attempts), 'coverage_complete': True, 'tokens': totals}

